create extension if not exists pgtap;
begin;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select ('9200000'||n||'-0000-4000-8000-000000000092')::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','seller92-'||n||'@example.test',now(),'{}','{}',now(),now() from generate_series(1,3)n;
insert into public.onboarding_progress(user_id,selected_track,selected_org_type,account_type_completed_at,completed_at) values('92000001-0000-4000-8000-000000000092','business','showroom_dealer',now(),now());
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"92000001-0000-4000-8000-000000000092","role":"authenticated"}',true);
select lives_ok($$select public.business_draft_save_v2(p_display_name=>'Showroom 92',p_legal_name=>'Showroom 92 LLC',p_org_type=>'showroom_dealer',p_governorate=>'cairo',p_city=>'maadi',p_contact_phone=>'+201012345678',p_activity_type=>'decor_showroom',p_detailed_address=>'')$$,'A: required onboarding without address is accepted');
select set_config('test.org',public.business_draft_submit_v2()::text,true);
select is((select status::text from public.organizations where id=current_setting('test.org')::uuid),'pending_verification','onboarding leaves approval pending');
select throws_ok(format('update public.organizations set status=''active'',is_verified=true where id=%L',current_setting('test.org')),'42501',null,'direct API self-activation denied');
select throws_ok($$update public.users set primary_account_type='engineer' where id='92000001-0000-4000-8000-000000000092'$$,'42501',null,'direct role assignment denied');
select set_config('test.product',public.create_product(current_setting('test.org')::uuid,'Draft before approval','finishing','piece')::text,true);
select is((select status::text from public.products where id=current_setting('test.product')::uuid),'draft','draft products remain allowed');
select throws_ok(format('select public.set_product_published(%L,true,1)',current_setting('test.product')),'42501',null,'unapproved / missing-address publishing denied');
select throws_ok(format('insert into app.showroom_legacy_seller_exceptions(organization_id) values(%L)',current_setting('test.org')),'42501',null,'cannot forge a legacy exception');
reset role;
select ok(not app.showroom_seller_ready(current_setting('test.org')::uuid),'A: new showroom cannot sell');
insert into public.verifications(id,subject_type,organization_id,verification_type,status,submitted_at) values('92a00001-0000-4000-8000-000000000092','organization',current_setting('test.org')::uuid,'organization','submitted',now());
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"55555555-5555-4555-8555-555555555555","role":"authenticated"}',true);
select lives_ok($$select public.review_start('92a00001-0000-4000-8000-000000000092')$$,'authorized administrator starts review');
select throws_ok($$select public.review_approve('92a00001-0000-4000-8000-000000000092',false)$$,'22023',null,'administrator cannot approve without detailed address');
select throws_ok($$select public.apply_organization_verification('92a00001-0000-4000-8000-000000000092')$$,'22023',null,'activation still requires approved review');
select set_config('request.jwt.claims','{"sub":"92000001-0000-4000-8000-000000000092","role":"authenticated"}',true);
select lives_ok(format('select public.branch_update_i18n(%L,null,null,%L,null,null)',(select primary_branch_id from public.memberships where organization_id=current_setting('test.org')::uuid),'10 Showroom Street'),'B: owner adds address through existing authorized branch editor');
select is((select is_verified from public.organizations where id=current_setting('test.org')::uuid),false,'address alone does not grant approval');
select throws_ok(format('select public.set_product_published(%L,true,1)',current_setting('test.product')),'42501',null,'complete address without approval cannot publish');
reset role;
select ok(app.showroom_profile_complete(current_setting('test.org')::uuid),'B: mandatory business data complete');
select ok(not app.showroom_seller_ready(current_setting('test.org')::uuid),'B: selling remains blocked pending approval');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"55555555-5555-4555-8555-555555555555","role":"authenticated"}',true);
select lives_ok($$select public.review_approve('92a00001-0000-4000-8000-000000000092',false)$$,'C: authorized approval accepted after completion');
select lives_ok($$select public.apply_organization_verification('92a00001-0000-4000-8000-000000000092')$$,'C: approved complete showroom activates');
select set_config('request.jwt.claims','{"sub":"92000001-0000-4000-8000-000000000092","role":"authenticated"}',true);
select lives_ok(format('select public.product_audiences_set(%L, array[''supplier''])',current_setting('test.product')),'C: audience chosen (Showroom publishing requires one)');
select lives_ok(format('select public.set_product_published(%L,true,1)',current_setting('test.product')),'C: activated approved showroom publishes');
select throws_ok(format('select public.branch_update_i18n(%L,null,null,%L,null,null)',(select primary_branch_id from public.memberships where organization_id=current_setting('test.org')::uuid),'   '),'22023',null,'active showroom cannot remove its address');
reset role;
select ok(app.showroom_seller_ready(current_setting('test.org')::uuid),'C: seller eligibility follows approval and completion');

-- Bootstrap synthetic historical records as the database owner. These existed
-- before the rollout in this fixture. Re-enable guards BEFORE any assertions.
insert into public.organizations(id,name,org_type,status,is_verified,created_by) values('92b00001-0000-4000-8000-000000000092','Historical seller','showroom_dealer','active',true,'92000003-0000-4000-8000-000000000092');
insert into public.branches(id,organization_id,name) values('92b00002-0000-4000-8000-000000000092','92b00001-0000-4000-8000-000000000092','Historical branch');
insert into public.memberships(id,user_id,organization_id,primary_branch_id,status) values('92b00003-0000-4000-8000-000000000092','92000003-0000-4000-8000-000000000092','92b00001-0000-4000-8000-000000000092','92b00002-0000-4000-8000-000000000092','active');
insert into public.membership_capabilities(membership_id,capability_key) values('92b00003-0000-4000-8000-000000000092','org.manage');
insert into app.showroom_legacy_seller_exceptions(organization_id,reason) values('92b00001-0000-4000-8000-000000000092','Synthetic pre-rollout approved seller');
alter table public.products disable trigger showroom_product_publish_complete;
insert into public.products(id,organization_id,name,category,unit,status,published_at,created_by) values('92c00001-0000-4000-8000-000000000092','92b00001-0000-4000-8000-000000000092','Historical published product','finishing','piece','published',now(),'92000003-0000-4000-8000-000000000092');
alter table public.products enable trigger showroom_product_publish_complete;
insert into app.showroom_legacy_published_products(product_id,organization_id) values('92c00001-0000-4000-8000-000000000092','92b00001-0000-4000-8000-000000000092');
insert into public.rfqs(id,requester_org_id,supplier_org_id,title,created_by) values('92d00001-0000-4000-8000-000000000092','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','92b00001-0000-4000-8000-000000000092','Historical order','11111111-1111-4111-8111-111111111111'),('92d00002-0000-4000-8000-000000000092','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','92b00001-0000-4000-8000-000000000092','New order','11111111-1111-4111-8111-111111111111');
alter table public.quotations disable trigger showroom_quotation_sell_complete;
insert into public.quotations(id,rfq_id,supplier_org_id,requester_org_id,status,submitted_at,decided_at,created_by) values('92e00001-0000-4000-8000-000000000092','92d00001-0000-4000-8000-000000000092','92b00001-0000-4000-8000-000000000092','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','accepted',now(),now(),'92000003-0000-4000-8000-000000000092'),('92e00002-0000-4000-8000-000000000092','92d00002-0000-4000-8000-000000000092','92b00001-0000-4000-8000-000000000092','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','accepted',now(),now(),'92000003-0000-4000-8000-000000000092');
insert into public.rfqs(id,requester_org_id,supplier_org_id,title,created_by,status) values('92d00003-0000-4000-8000-000000000092','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','92b00001-0000-4000-8000-000000000092','Historical submitted quote','11111111-1111-4111-8111-111111111111','quoted');
insert into public.quotations(id,rfq_id,supplier_org_id,requester_org_id,status,submitted_at,created_by) values('92e00003-0000-4000-8000-000000000092','92d00003-0000-4000-8000-000000000092','92b00001-0000-4000-8000-000000000092','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','submitted',now(),'92000003-0000-4000-8000-000000000092');
alter table public.quotations enable trigger showroom_quotation_sell_complete;
alter table public.orders disable trigger trg_zz_showroom_order_sell_complete;
insert into public.orders(id,quotation_id,rfq_id,requester_org_id,supplier_org_id,title,created_by) values('92f00001-0000-4000-8000-000000000092','92e00001-0000-4000-8000-000000000092','92d00001-0000-4000-8000-000000000092','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','92b00001-0000-4000-8000-000000000092','Historical order','11111111-1111-4111-8111-111111111111');
alter table public.orders enable trigger trg_zz_showroom_order_sell_complete;
insert into app.showroom_legacy_orders(order_id,organization_id) values('92f00001-0000-4000-8000-000000000092','92b00001-0000-4000-8000-000000000092');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"92000002-0000-4000-8000-000000000092","role":"authenticated"}',true);
select ok(app.showroom_listing_visible('92b00001-0000-4000-8000-000000000092','92c00001-0000-4000-8000-000000000092'),'legacy product remains visible to other accounts (the rule every catalog read path now enforces)');
select throws_ok($$select public.branch_update_i18n('92b00002-0000-4000-8000-000000000092',null,null,'Cross tenant attack',null,null)$$,'22023',null,'cross-tenant address changes denied');
select set_config('request.jwt.claims','{"sub":"92000003-0000-4000-8000-000000000092","role":"authenticated"}',true);
select ok((public.my_profile_completion()->'missing') ? 'organization_address','affected legacy seller marked for profile completion');
select set_config('test.legacy_product',public.create_product('92b00001-0000-4000-8000-000000000092','New legacy draft','finishing','piece')::text,true);
select throws_ok(format('select public.set_product_published(%L,true,1)',current_setting('test.legacy_product')),'42501',null,'legacy seller cannot publish new product without address');
select lives_ok($$select public.start_order('92f00001-0000-4000-8000-000000000092',1)$$,'captured existing order operations continue');
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
select throws_ok($$select public.create_order_from_quotation('92e00002-0000-4000-8000-000000000092')$$,'42501',null,'uncaptured new selling order blocked until address completion');
select throws_ok($$select public.decide_quotation('92e00003-0000-4000-8000-000000000092',true,1)$$,'42501',null,'acceptance denied after showroom loses selling eligibility');
select is((select status::text from public.rfqs where id='92d00003-0000-4000-8000-000000000092'),'quoted','denied acceptance does not close the RFQ');
select lives_ok($$select public.decide_quotation('92e00003-0000-4000-8000-000000000092',false,1)$$,'requester may still reject an ineligible supplier quotation');
select set_config('request.jwt.claims','{"sub":"92000003-0000-4000-8000-000000000092","role":"authenticated"}',true);
select lives_ok($$select public.branch_update_i18n('92b00002-0000-4000-8000-000000000092',null,null,'10 Legacy Showroom Street',null,null)$$,'legacy owner remedies address via existing editor');
select lives_ok(format('select public.product_audiences_set(%L, array[''supplier''])',current_setting('test.legacy_product')),'legacy: audience chosen (Showroom publishing requires one)');
select lives_ok(format('select public.set_product_published(%L,true,1)',current_setting('test.legacy_product')),'legacy new publishing enabled after remediation');
select throws_ok($$select public.branch_update_i18n('92b00002-0000-4000-8000-000000000092',null,null,' ',null,null)$$,'22023',null,'closed legacy exception cannot be reopened by clearing address');
reset role;
select isnt((select closed_at from app.showroom_legacy_seller_exceptions where organization_id='92b00001-0000-4000-8000-000000000092'),null,'legacy remediation recorded');
select is((select closed_by from app.showroom_legacy_seller_exceptions where organization_id='92b00001-0000-4000-8000-000000000092'),'92000003-0000-4000-8000-000000000092'::uuid,'remediating actor audited');
select ok(not has_table_privilege('authenticated','app.showroom_legacy_seller_exceptions','insert'),'legacy ledger cannot be expanded through Data API');
select * from finish();
rollback;
